"use client";
// Adapted from shadcn/ui (MIT). See components/ui/LICENSE and ORIGIN.json.
import { useSyncExternalStore } from "react";
const query = "(max-width: 767px)";
function subscribe(onChange: () => void) {
  const media = window.matchMedia(query);
  media.addEventListener("change", onChange);
  return () => media.removeEventListener("change", onChange);
}
export function useIsMobile() {
  return useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );
}

// Lucide adapter for shadcn/ui's registry icon placeholders (MIT).
import {
  CheckIcon,
  CopyIcon,
  XIcon,
  CircleCheckIcon,
  InfoIcon,
  TriangleAlertIcon,
  OctagonXIcon,
  Loader2Icon,
  ChevronRightIcon,
  type LucideProps,
} from "lucide-react";

const icons = {
  CheckIcon,
  CopyIcon,
  XIcon,
  CircleCheckIcon,
  InfoIcon,
  TriangleAlertIcon,
  OctagonXIcon,
  Loader2Icon,
  ChevronRightIcon,
};
export function IconPlaceholder({
  lucide,
  hugeicons,
  tabler,
  phosphor,
  remixicon,
  ...props
}: LucideProps & {
  lucide?: string;
  hugeicons?: string;
  tabler?: string;
  phosphor?: string;
  remixicon?: string;
}) {
  void hugeicons;
  void tabler;
  void phosphor;
  void remixicon;
  const Icon = icons[lucide as keyof typeof icons] ?? InfoIcon;
  return <Icon {...props} />;
}

// Portable link adapter for shadcn/ui's MIT examples.
import type { ComponentProps } from "react";
export default function PreviewLink({ href, ...props }: ComponentProps<"a">) {
  const target = href?.startsWith("/docs")
    ? `https://ui.shadcn.com${href}`
    : href;
  return (
    <a
      {...props}
      href={target}
      target={target?.startsWith("https://") ? "_blank" : undefined}
      rel={target?.startsWith("https://") ? "noreferrer" : undefined}
    />
  );
}

